// Mobile menu
const burger = document.getElementById('burger'), mm = document.getElementById('mobileMenu');
if (burger && mm) {
  burger.addEventListener('click', () => {
    burger.classList.toggle('active'); mm.classList.toggle('open');
    document.body.style.overflow = mm.classList.contains('open') ? 'hidden' : '';
  });
  mm.querySelectorAll('a').forEach(a => a.addEventListener('click', () => {
    burger.classList.remove('active'); mm.classList.remove('open'); document.body.style.overflow = '';
  }));
}

// Lightbox
const items = document.querySelectorAll('.gallery__item img');
const lb = document.getElementById('lightbox');
const lbImg = document.getElementById('lbImg');
let current = 0;
const srcs = Array.from(items).map(i => i.src);

items.forEach((img, i) => {
  img.parentElement.addEventListener('click', () => {
    current = i;
    lbImg.src = srcs[current];
    lb.classList.add('open');
    document.body.style.overflow = 'hidden';
  });
});

document.getElementById('lbClose').addEventListener('click', () => {
  lb.classList.remove('open');
  document.body.style.overflow = '';
});
document.getElementById('lbPrev').addEventListener('click', () => {
  current = (current - 1 + srcs.length) % srcs.length;
  lbImg.src = srcs[current];
});
document.getElementById('lbNext').addEventListener('click', () => {
  current = (current + 1) % srcs.length;
  lbImg.src = srcs[current];
});
lb.addEventListener('click', (e) => {
  if (e.target === lb) { lb.classList.remove('open'); document.body.style.overflow = ''; }
});
document.addEventListener('keydown', (e) => {
  if (!lb.classList.contains('open')) return;
  if (e.key === 'Escape') { lb.classList.remove('open'); document.body.style.overflow = ''; }
  if (e.key === 'ArrowLeft') { current = (current - 1 + srcs.length) % srcs.length; lbImg.src = srcs[current]; }
  if (e.key === 'ArrowRight') { current = (current + 1) % srcs.length; lbImg.src = srcs[current]; }
});
